/* Planes reales, sin pasarela de pago ni captura de tarjetas: el pago es por transferencia y lo confirma Agendappx. */
(function(global){'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const moneda=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:Number.isInteger(n)?0:2}).format(n);
 let catalogo=null;async function cargarCatalogo(){const r=await fetch('/api/planes/catalogo',{cache:'no-store',signal:AbortSignal.timeout(12000)});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudieron consultar los planes.');catalogo=d;return d;}
 const comparar=d=>`<div class="planes-table"><table><caption>Compara los planes</caption><thead><tr><th>Incluye</th>${d.planes.map(p=>`<th>${esc(p.nombre)}</th>`).join('')}</tr></thead><tbody><tr><th>Personas</th>${d.planes.map(p=>`<td>${p.personas??'Sin límite'}</td>`).join('')}</tr><tr><th>Admin</th>${d.planes.map(p=>`<td>${p.admins??'Sin límite'}</td>`).join('')}</tr><tr><th>Mensajes de citas / mes</th><td>600</td><td>600</td><td>600</td></tr><tr><th>Comisión por cita</th><td>0 %</td><td>0 %</td><td>0 %</td></tr></tbody></table></div>`;
 function tarjetas(d,anual,actual=null){return `<p class="planes-intro">30 días gratis, sin tarjeta. Precios en MXN, IVA incluido.</p><div class="seg planes-periodo" role="group" aria-label="Periodo del plan"><button type="button" data-periodo="mensual" aria-pressed="${!anual}" aria-selected="${!anual}">Mensual</button><button type="button" data-periodo="anual" aria-pressed="${anual}" aria-selected="${anual}">Anual · 2 meses gratis</button></div><div class="planes-fundadora"><b>Precio de fundadora · $199 al mes</b><p>Plan Salón para los primeros 20 negocios. ${d.fundadoras.disponibles>0?`Quedan ${d.fundadoras.disponibles} lugares.`:'Los 20 lugares ya fueron asignados.'}${actual?.fundadora_numero?' Tu salón tiene el lugar '+actual.fundadora_numero+'.':''}</p><p>El beneficio se conserva mientras mantengas tu plan.${d.cobrosHabilitados?'':' Todavía no se realizan cobros.'}</p></div><div class="planes-cards">${d.planes.map(p=>{const fundador=actual?.fundadora_numero&&p.id==='salon',m=fundador?199:p.mensual,total=m*(anual?10:1);return `<article class="plan-card ${p.recomendado?'recommended':''}"><div class="plan-card-head"><h2>${esc(p.nombre)}</h2>${p.recomendado?'<span>Recomendado</span>':''}</div><p>${esc(p.descripcion)}</p><div class="plan-precio"><b>${moneda(total)}</b><small>MXN / ${anual?'año':'mes'}</small></div>${anual?`<p>${moneda(total/12)} al mes, con pago anual.</p>`:''}<ul><li>${p.personas===null?'Personas sin límite':p.personas+' persona'+(p.personas===1?'':'s')}</li><li>${p.admins===null?'Admin sin límite':p.admins+' Admin'}</li><li>Agenda, clientas y servicios con fotos</li><li>Perfil opcional en Explorar y Social</li><li>WhatsApp sujeto a consentimiento y configuración</li></ul><button type="button" class="btn ${p.recomendado?'fill':''}" data-elegir-plan="${p.id}" ${['legado','pausada','pagado','gracia'].includes(actual?.estado)?'disabled':''}>${actual?'Usar en mi prueba':'Crear salón con '+esc(p.nombre)}</button></article>`;}).join('')}</div>${comparar(d)}<div class="group planes-faq"><details><summary>¿Se realizará algún cobro?</summary><p>${d.cobrosHabilitados?'Nada se cobra automáticamente. La prueba no pide tarjeta; si quieres seguir, pagas tu plan por transferencia desde Mi plan.':'No. La prueba no pide tarjeta y los cobros aún no están habilitados. Los precios se muestran para que elijas.'}</p></details><details><summary>¿Qué pasa al terminar los 30 días?</summary><p>El salón nuevo queda en pausa para nuevos cambios, conservando sus datos para consulta. Cambiar de plan no reinicia la prueba. Los accesos existentes se conservan.</p></details><details><summary>¿Puedo cambiar de plan?</summary><p>Durante tu prueba puedes elegir otro plan si tu equipo cabe en sus límites. Nunca se borran integrantes para bajar de plan.</p></details><details><summary>¿Cómo se pagará y cancelará?</summary><p>Próximamente. Antes de habilitar cobros se definirá el proveedor, la facturación y la cancelación. Por ahora no hay cargos automáticos ni contratos de pago.</p></details><details><summary>¿WhatsApp y promociones están activos?</summary><p>Elegir un plan no vincula números ni activa mensajes. Se conservan el consentimiento, las pausas y los límites existentes.</p></details></div>`;}
 function publico(root){let anual=false;root.innerHTML='<p role="status">Consultando planes…</p>';cargarCatalogo().then(d=>{const dibujar=()=>root.innerHTML=tarjetas(d,anual);dibujar();root.addEventListener('click',e=>{const b=e.target.closest('[data-periodo],[data-elegir-plan]');if(!b)return;if(b.dataset.periodo){anual=b.dataset.periodo==='anual';dibujar();}else {try{localStorage.setItem('agendappx.registro.plan',b.dataset.elegirPlan);}catch{}location.assign('/#registro');}});}).catch(e=>{root.innerHTML='<p role="status">'+esc(e.message)+'</p><button type="button" id="planes-reintentar" class="btn">Reintentar</button>';root.querySelector('button').onclick=()=>publico(root);});}
 function crear(ctx){const {openSheet,closeSheet,navSheet,toast}=ctx;let datos=null,anual=false,activa=null;
 async function api(path='',method='GET',data){const s=await global.AgendappxCuentas?.sesion();if(!s||s.rol!=='admin'||s.aal!=='aal2')throw new Error('Inicia sesión como Admin y verifica los dos pasos.');if(!navigator.onLine)throw new Error('Conéctate para consultar o guardar tu plan.');const r=await fetch('/api/negocios/'+s.negocioId+'/plan'+path,{method,headers:{Authorization:'Bearer '+s.accessToken,'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{}),cache:'no-store',signal:AbortSignal.timeout(12000)});const d=await r.json(),actual=await global.AgendappxCuentas?.sesion();if(actual?.usuarioId!==s.usuarioId||actual?.negocioId!==s.negocioId)throw new Error('Tu cuenta cambió. Abre Mi plan de nuevo.');if(!r.ok)throw new Error(d.error||'No se pudo consultar el plan.');return d;}
 function usarHoja(titulo,contenido){openSheet(navSheet(titulo,'')+contenido,titulo,root=>{activa=root;root.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeSheet();});});return activa;}
 async function abrir(){const root=usarHoja('Mi plan','<p class="foot" role="status" id="plan-status">Consultando tu plan…</p>');try{datos=await api();if(!root.isConnected)return;anual=datos.anual;dibujarMiPlan(root);}catch(e){if(root.isConnected&&root.querySelector('#plan-status'))root.querySelector('#plan-status').textContent=e.message;}}
 function dibujarMiPlan(root){root.innerHTML='<div class="grab"></div>'+navSheet('Mi plan','')+`<div class="mi-plan-resumen"><h1>${esc(datos.nombre)}</h1><span class="plan-estado">${{legado:'Acceso existente conservado',pausada:'Prueba terminada',pagado:'Pagado · '+datos.diasRestantes+' días',gracia:'Pago vencido'}[datos.estado]||datos.diasRestantes+' días de prueba'}</span><p>${resumenEstado()}</p>${datos.fundadora_numero?`<p>Fundadora #${datos.fundadora_numero} · plan Salón a $199 MXN/mes.</p>`:''}</div><p class="gh">Lo que usas</p><div class="group">${[['Personas','personas'],['Admin','admins'],['WhatsApp vinculados','whatsapp'],['Mensajes de citas este mes','mensajes']].map(([n,k])=>`<div class="cell"><span class="l">${n}</span><b>${datos.uso[k]}${datos.limites[k]!=null?' / '+datos.limites[k]:''}</b></div>`).join('')}</div><div class="group" style="margin-top:20px"><button class="cell" type="button" data-plan-ver>Ver planes y comparar</button><button class="cell" type="button" data-plan-factura><span class="l">Datos de factura<small>Para cuando se habilite la facturación</small></span></button>${datos.cobrosHabilitados?'':'<div class="cell"><span class="l">Agregar tarjeta</span><span class="plan-estado">Próximamente</span></div>'}</div>${seccionPago()}`;root.onclick=(e=>{const b=e.target.closest('[data-plan-ver],[data-plan-factura],[data-pago]');if(b?.hasAttribute('data-plan-ver'))void verPlanes();if(b?.hasAttribute('data-plan-factura'))factura();if(b?.dataset.pago)void accionPago(b,root);});}

 const largo=v=>esc(new Intl.DateTimeFormat('es-MX',{dateStyle:'long',timeZone:'America/Mexico_City'}).format(new Date(v)));
 function resumenEstado(){const e=datos.estado;if(e==='legado')return 'Tu acceso actual no cambia ni se convierte automáticamente en una suscripción.';
  if(e==='pagado')return 'Tu plan está pagado hasta el '+largo(datos.pagado_hasta)+'. Nada se cobra automáticamente: antes de esa fecha paga el siguiente periodo por transferencia.';
  if(e==='gracia')return 'Tu periodo pagado terminó el '+largo(datos.pagado_hasta)+'. Tienes 3 días para transferir sin perder el acceso.';
  if(e==='pausada')return datos.cobrosHabilitados?'Tus datos siguen guardados. Paga tu plan por transferencia para seguir agregando citas.':'Tus datos siguen guardados. Los cobros aún no están habilitados.';
  return 'Tu prueba termina el '+largo(datos.prueba_fin)+'. '+(datos.cobrosHabilitados?'No se te cobra nada automáticamente; si te gusta, paga tu plan por transferencia.':'No se te cobrará al terminar.');}
 const NOMBRES={solo:'Solo',salon:'Salón',pro:'Pro'},ESTADOS={pendiente:'Esperando tu transferencia',reportado:'Por confirmar',confirmado:'Confirmado',rechazado:'Rechazado'};
 function seccionPago(){if(datos.estado==='legado')return '';const t=datos.transferencia,abierto=(datos.pagos||[]).find(p=>p.estado==='pendiente'||p.estado==='reportado'),historial=(datos.pagos||[]).filter(p=>p!==abierto);
  let html='<p class="gh">Pagar mi plan</p>';
  if(!datos.cobrosHabilitados||!t)html+='<div class="group"><p class="foot">Los pagos todavía no están habilitados. Te avisaremos antes de que termine tu prueba.</p></div>';
  else if(abierto)html+=`<div class="group pago-transferencia"><div class="cell"><span class="l">Total a transferir<small>Plan ${esc(NOMBRES[abierto.plan])} ${abierto.anual?'anual':'mensual'}</small></span><b>${moneda(abierto.monto)}</b></div><div class="cell"><span class="l">Banco</span><b>${esc(t.banco)}</b></div><div class="cell"><span class="l">CLABE</span><b style="letter-spacing:.5px">${esc(t.clabe.replace(/(\d{3})(\d{3})(\d{11})(\d)/,'$1 $2 $3 $4'))}</b></div><button type="button" class="cell" data-pago="copiar-clabe">Copiar CLABE</button><div class="cell"><span class="l">A nombre de</span><b>${esc(t.titular)}</b></div><div class="cell"><span class="l">Concepto o referencia<small>Escríbela tal cual en tu transferencia</small></span><b>${esc(abierto.referencia)}</b></div><button type="button" class="cell" data-pago="copiar-ref">Copiar referencia</button></div>`+
   (abierto.estado==='reportado'?'<p class="foot">Recibimos tu aviso. Confirmaremos tu pago en cuanto lo veamos en el banco (normalmente el mismo día hábil) y tu plan se activará solo.</p>':`<label class="cell" style="display:block;margin:0 16px"><span class="l">Nota opcional<small>Banco desde el que transferiste, hora o últimos 4 dígitos</small></span><input class="in" id="pago-nota" maxlength="200" style="width:100%;text-align:left"></label><button type="button" class="cta" data-pago="reportar" data-id="${esc(abierto.id)}">Ya transferí</button><button type="button" class="cell" data-pago="cancelar" data-id="${esc(abierto.id)}" style="margin-top:8px">Cancelar este pago</button>`);
  else html+=`<div class="group"><label class="cell"><span class="l">Plan</span><select class="in" id="pago-plan" style="max-width:55%">${['solo','salon','pro'].map(id=>`<option value="${id}" ${id===datos.plan?'selected':''}>${NOMBRES[id]}</option>`).join('')}</select></label><label class="cell"><span class="l">Periodo</span><select class="in" id="pago-periodo" style="max-width:55%"><option value="mensual" ${datos.anual?'':'selected'}>Mensual</option><option value="anual" ${datos.anual?'selected':''}>Anual · 2 meses gratis</option></select></label></div><button type="button" class="cta" data-pago="solicitar">Pagar por transferencia</button><p class="foot">Te mostramos la CLABE, el monto y tu referencia. Tu plan se activa cuando confirmemos el depósito. Sin tarjeta y sin cargos automáticos.</p>`;
  html+='<p class="gh">Pagos</p><div class="group">'+(historial.length?historial.map(p=>`<div class="cell"><span class="l">${moneda(p.monto)} · ${esc(NOMBRES[p.plan])} ${p.anual?'anual':'mensual'}<small>${esc(p.referencia)} · ${esc(new Date(p.creadoEn).toLocaleDateString('es-MX'))}${p.periodoFin?' · cubre hasta el '+largo(p.periodoFin):''}${p.motivo?' · '+esc(p.motivo):''}</small></span><span class="plan-estado">${esc(ESTADOS[p.estado]||p.estado)}</span></div>`).join(''):'<p class="foot">No hay pagos registrados.</p>')+'</div>';
  return html;}
 async function accionPago(b,root){const tipo=b.dataset.pago,t=datos.transferencia,abierto=(datos.pagos||[]).find(p=>p.estado==='pendiente'||p.estado==='reportado');
  if(tipo==='copiar-clabe'||tipo==='copiar-ref'){try{await navigator.clipboard.writeText(tipo==='copiar-clabe'?t.clabe:abierto.referencia);toast('Copiado.');}catch{toast(tipo==='copiar-clabe'?t.clabe:abierto.referencia);}return;}
  if(tipo==='cancelar'&&!confirm('¿Cancelar este pago? Podrás pedir uno nuevo después.'))return;
  b.disabled=true;try{
   if(tipo==='solicitar')await api('/pago','POST',{plan:root.querySelector('#pago-plan').value,anual:root.querySelector('#pago-periodo').value==='anual'});
   if(tipo==='reportar'){await api('/pago/reportar','POST',{id:b.dataset.id,nota:root.querySelector('#pago-nota')?.value.trim().slice(0,200)||''});toast('Gracias. Te avisaremos al confirmar tu pago.');}
   if(tipo==='cancelar')await api('/pago/cancelar','POST',{id:b.dataset.id});
   datos=await api();if(root.isConnected)dibujarMiPlan(root);}catch(e){toast(e.message);b.disabled=false;}}
 async function verPlanes(){const root=usarHoja('Planes','<p class="foot" role="status" id="plan-status">Consultando planes…</p>');try{const d=await cargarCatalogo();if(!root.isConnected)return;const dibujar=()=>root.innerHTML='<div class="grab"></div>'+navSheet('Planes','')+tarjetas(d,anual,datos)+'<p class="foot" id="plan-feedback" role="status"></p>';dibujar();let ocupado=false;root.addEventListener('click',async e=>{const b=e.target.closest('[data-periodo],[data-elegir-plan]');if(!b||ocupado)return;if(b.dataset.periodo){anual=b.dataset.periodo==='anual';dibujar();}else {ocupado=true;b.disabled=true;try{await api('/elegir','POST',{plan:b.dataset.elegirPlan,anual});toast('Plan de prueba guardado. No se realizó ningún cobro.');await abrir();}catch(e){root.querySelector('#plan-feedback').textContent=e.message;}finally{ocupado=false;b.disabled=false;}}});}catch(e){if(root.isConnected&&root.querySelector('#plan-status'))root.querySelector('#plan-status').textContent=e.message;}}
 function factura(){const campos=[['rfc','RFC'],['razonSocial','Razón social'],['codigoPostal','Código postal'],['regimen','Régimen fiscal'],['usoCFDI','Uso de CFDI'],['correo','Correo para factura']],root=usarHoja('Datos de factura',`<p class="foot">Solo se guardan tus datos. Aún no se emiten facturas ni se realizan cobros.</p><form id="plan-factura-form"><div class="group">${campos.map(([k,n])=>`<label class="cell"><span class="l">${n}</span><input class="in" name="${k}" maxlength="250" type="${k==='correo'?'email':'text'}" value="${esc(datos.factura?.[k]||'')}" style="max-width:55%"></label>`).join('')}</div><button type="submit" class="cta">Guardar datos</button></form><p class="foot" role="status" id="factura-feedback"></p>`);root.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const b=root.querySelector('[type=submit]');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));d.rfc=d.rfc.toUpperCase().trim();await api('/factura','PUT',d);datos.factura=d;root.querySelector('#factura-feedback').textContent='Datos guardados. Todavía no se emiten facturas.';}catch(e){root.querySelector('#factura-feedback').textContent=e.message;}finally{b.disabled=false;}});}
 return {abrir};}
 global.AgendappxPlanes={crear,publico};
})(window);
